CREATE FUNCTION authz_int."fm.group_members:column group_id after:holds"(p_row "fm"."group_members") RETURNS boolean
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT coalesce(authz_int."group__manage__has"("group_members"."group_id"), false) FROM pg_catalog.unnest(ARRAY[p_row]) AS "group_members";
END;

-- checked on the row after the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update_after group_id" BEFORE UPDATE ON "fm"."group_members" FOR EACH ROW
  WHEN ((OLD."group_id" IS DISTINCT FROM NEW."group_id")
    AND pg_catalog.row_security_active('"fm"."group_members"'::pg_catalog.regclass)
    AND NOT authz_int."fm.group_members:column group_id after:holds"(pg_catalog.jsonb_populate_record(NULL::"fm"."group_members", pg_catalog.to_jsonb(NEW))))
  EXECUTE FUNCTION authz_int."fm.group_members:column group_id after"();

CREATE FUNCTION authz_gen."fm.group_members:column id, user_id:items"(p_row "fm"."group_members") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."fm.group_members:seen"("group_members"."id") THEN ARRAY[
    coalesce(coalesce((false), false), false),
    coalesce((SELECT authz_int.scope_cmd('fm.group_members', 'update')), false),
    coalesce(true, false),
    coalesce(coalesce((false), false), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[4]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "group_members";
END;

-- fm.group_members update id, user_id (line 93): nobody
-- Whether the rule holds for a row: called by the trigger's WHEN, which is kept parsed, as a policy is, so the app
-- role uses it without naming it (authz_int)
CREATE FUNCTION authz_int."fm.group_members:column id, user_id:holds"(p_row "fm"."group_members") RETURNS boolean
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT coalesce(coalesce((false), false), false) FROM pg_catalog.unnest(ARRAY[p_row]) AS "group_members";
END;

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update id, user_id" BEFORE UPDATE ON "fm"."group_members" FOR EACH ROW
  WHEN ((OLD."id" IS DISTINCT FROM NEW."id"
     OR OLD."user_id" IS DISTINCT FROM NEW."user_id")
    AND pg_catalog.row_security_active('"fm"."group_members"'::pg_catalog.regclass)
    AND NOT authz_int."fm.group_members:column id, user_id:holds"(pg_catalog.jsonb_populate_record(NULL::"fm"."group_members", pg_catalog.to_jsonb(OLD))))
  EXECUTE FUNCTION authz_int."fm.group_members:column id, user_id"();

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

